def Target : Prop :=
  ∀ K : Def1, Def3 K →
    (¬ Theory.RE (K : ArithmeticTheory)) ∨ ∃ σ : ArithmeticSentence, Def2 σ ∧ σ ∉ K ∧ (∼σ) ∉ K

